dict(t='गार्डन हर्ब डिप',p='8',s='रेसिपी का 1/8 भाग',
i=['1 कप व्हिप्ड क्रीम चीज़','1 कली लहसुन, बारीक कटा हुआ','1 बड़ा चम्मच ऑलिव ऑयल','1 बड़ा चम्मच ताज़ी चाइव्स, कटी हुई','1 बड़ा चम्मच ताज़ी तुलसी, कटी हुई','1 बड़ा चम्मच फ्लैट लीफ़ अजमोद (पार्सले), कटा हुआ','6 बूँद Tabasco®'],
st=['एक कटोरे में क्रीम चीज़, लहसुन और तेल मिलाएँ और इलेक्ट्रिक मिक्सर से मलाईदार होने तक फेंटें।','स्पैचुला से बाकी सामग्री को मिश्रण में धीरे से मिलाएँ।','परोसने के कटोरे में डालें, प्लास्टिक रैप से ढकें और लगभग 30 मिनट फ्रिज में ठंडा करें।','कटी सब्जियों या कम सोडियम वाले क्रैकर के साथ परोसें।'],
h=['सब्जियाँ स्वस्थ आहार का महत्वपूर्ण हिस्सा हैं। सैंडविच के साथ या नाश्ते के रूप में कच्ची सब्जियाँ खाना उन्हें अपनी भोजन योजना में जोड़ने का आसान तरीका हो सकता है। अपनी कच्ची सब्जियों को डिप के साथ परोसना मज़ेदार और स्वादिष्ट हो सकता है। आमतौर पर कच्ची खाई जाने वाली कम पोटैशियम वाली सब्जियों में शतावरी, ब्रोकली, गाजर, फूलगोभी, सेलरी, खीरा, स्नैप पीज़, शिमला मिर्च और मूली शामिल हैं।\n\nकिराने की दुकान से खरीदे गए डिप में सोडियम के साथ-साथ फॉस्फेट योजक भी अधिक मात्रा में हो सकते हैं। इनसे बचने के लिए डिप घर पर ही तैयार करना सबसे अच्छा है। अपना पसंदीदा डिप बनाने के लिए कई तरह की सामग्री के साथ प्रयोग करें। सावर क्रीम या व्हिप्ड क्रीम चीज़ जैसे आधार से शुरुआत करें और स्वाद के लिए कई तरह की जड़ी-बूटियाँ और मसाले डालें। बारीक कटा ताज़ा प्याज़ या लहसुन भी बहुत स्वाद जोड़ सकता है। चाहें तो तीखे सॉस की एक झलक से थोड़ा तीखापन डालें। अपने पसंदीदा स्वाद खोजने के लिए अलग-अलग स्वादों को मिलाकर देखें।\n\nसादा योगर्ट डिप के आधार के लिए कम कैलोरी वाला विकल्प हो सकता है, लेकिन इसमें पोटैशियम अधिक होता है। कम वसा वाली सावर क्रीम या क्रीम चीज़ भी डिप की कैलोरी कम कर सकती है, लेकिन इन्हें खरीदते समय सावधानी बरतें क्योंकि इनमें आमतौर पर फॉस्फेट योजक होते हैं। अपने रजिस्टर्ड डाइटीशियन से पूछें कि डिप की कौन सी सामग्री आपके लिए सही है।'],
f=['2 फैट (वसा)']),
